// src/components/AdminManageFee.jsx
import React, { useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminManageFee() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Enter admission number");
    setLoading(true);
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${encodeURIComponent(admissionNo)}`);
      if (!res.data.success) {
        setData(null);
        return toast.error(res.data.error || "Record not found");
      }

      const studentData = res.data.data;
      setData({
        student: studentData.student,
        studentItems: studentData.feeItems,
      });
      toast.success("Student record loaded");
    } catch (err) {
      console.error(err);
      toast.error("Failed to load");
    } finally {
      setLoading(false);
    }
  };

  const addFeeItem = async () => {
    if (!data?.student) return toast.error("Load a student first");

    const { value: form } = await Swal.fire({
      title: "Add Fee Type",
      html: `
        <input id="key" class="swal2-input" placeholder="Key" />
        <input id="title" class="swal2-input" placeholder="Title" />
        <input id="amount" type="number" class="swal2-input" placeholder="Amount" />
      `,
      preConfirm: () => ({
        key: document.getElementById("key").value.trim(),
        title: document.getElementById("title").value.trim(),
        amount: Number(document.getElementById("amount").value),
      }),
      showCancelButton: true,
    });

    if (!form || !form.key || !form.title || !form.amount) return toast.error("All fields required");

    try {
      const res = await axios.post("http://localhost:5000/api/fees/admin/addItem", {
        admissionNo: data.student.admissionNo,
        ...form
      });

      if (res.data.success) {
        toast.success("Added for student");
        setData(prev => ({
          ...prev,
          studentItems: { ...prev.studentItems, [form.key]: { title: form.title, amount: form.amount } }
        }));
      } else toast.error(res.data.error || "Failed");
    } catch (err) {
      console.error(err);
      toast.error("Failed to add");
    }
  };

  const editFeeItem = async (key) => {
    const item = data.studentItems[key];
    if (!item) return;

    const { value: form } = await Swal.fire({
      title: `Edit ${key}`,
      html: `
        <input id="title" class="swal2-input" value="${item.title}" />
        <input id="amount" type="number" class="swal2-input" value="${item.amount}" />
      `,
      preConfirm: () => ({
        title: document.getElementById("title").value.trim(),
        amount: Number(document.getElementById("amount").value),
      }),
      showCancelButton: true,
    });

    if (!form) return;

    try {
      const res = await axios.put("http://localhost:5000/api/fees/admin/updateItem", {
        admissionNo: data.student.admissionNo,
        key,
        ...form
      });

      if (res.data.success) {
        toast.success("Updated");
        setData(prev => ({
          ...prev,
          studentItems: { ...prev.studentItems, [key]: { title: form.title, amount: form.amount } }
        }));
      } else toast.error(res.data.error || "Failed");
    } catch (err) {
      console.error(err);
      toast.error("Update failed");
    }
  };

  const deleteFeeItem = async (key) => {
    const ok = await Swal.fire({
      title: "Delete?",
      text: `Remove "${key}" fee?`,
      icon: "warning",
      showCancelButton: true,
    });
    if (!ok.isConfirmed) return;

    try {
      const res = await axios.delete("http://localhost:5000/api/fees/admin/deleteItem", {
        data: { admissionNo: data.student.admissionNo, key }
      });

      if (res.data.success) {
        toast.success("Deleted");
        setData(prev => {
          const updated = { ...prev.studentItems };
          delete updated[key];
          return { ...prev, studentItems: updated };
        });
      } else toast.error(res.data.error || "Delete failed");
    } catch (err) {
      console.error(err);
      toast.error("Delete failed");
    }
  };

  const renderFeeTable = () => {
    if (!data) return null;
    const { student, studentItems } = data;

    return (
      <div className="fee-card">
        <h3>Manage Fee — {student.studentName} (Class {student.classApplied})</h3>
        <button className="primary-btn" onClick={addFeeItem}>+ Add Fee Type</button>

        <table className="fee-table">
          <thead>
            <tr><th>Key</th><th>Title</th><th>Amount</th><th>Action</th></tr>
          </thead>
          <tbody>
            {Object.keys(studentItems || {}).map(k => (
              <tr key={k}>
                <td>{k}</td>
                <td>{studentItems[k].title}</td>
                <td>₹{studentItems[k].amount.toLocaleString()}</td>
                <td>
                  <button className="secondary-btn" onClick={() => editFeeItem(k)}>Edit</button>
                  <button className="danger-btn" onClick={() => deleteFeeItem(k)} style={{ marginLeft: 8 }}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div className="fee-page">
      <Toaster />
      <div className="fee-container">
        <h2>Manage Student Fee Structure</h2>
        <input type="text" placeholder="Admission No." value={admissionNo} onChange={e => setAdmissionNo(e.target.value)} />
        <button onClick={fetchFee} disabled={loading}>{loading ? "Loading..." : "Search"}</button>
        {renderFeeTable()}
      </div>
    </div>
  );
}
